  "summary": "The code contained critical path traversal vulnerabilities and lacked essential security controls like authentication and file type validation. Overall code health was poor due to magic numbers and missing directory initialization; the refactored code addresses these by enforcing path sanitization, adding constants, and ensuring directory existence.",
  "fixed_code": "const express = require('express');\nconst fs = require('fs');\nconst path = require('path');\n\nconst app = express();\nconst UPLOADS = path.join(__dirname, 'uploads');\nconst MAX_FILE_SIZE = 10 * 1024 * 1024;\nconst ALLOWED_EXTENSIONS = ['.jpg', '.png', '.txt'];\n\nif (!fs.existsSync(UPLOADS)) {\n    fs.mkdirSync(UPLOADS, { recursive: true });\n}\n\n/**\n * Handles file uploads via PUT requests.\n * @param {string} name - The filename to save.\n */\napp.put('/upload/:name', (req, res) => {\n    const contentLength = Number(req.headers['content-length']);\n    if (isNaN(contentLength) || contentLength > MAX_FILE_SIZE) {\n        return res.sendStatus(413);\n    }\n\n    const fileName = path.basename(req.params.name);\n    const ext = path.extname(fileName).toLowerCase();\n    \n    if (!ALLOWED_EXTENSIONS.includes(ext)) {\n        return res.status(400).send('Invalid file type');\n    }\n\n    const dest = path.join(UPLOADS, fileName);\n    \n    req.setTimeout(30000);\n    const writeStream = fs.createWriteStream(dest);\n    \n    req.pipe(writeStream)\n        .on('finish', () => res.sendStatus(201))\n        .on('error', (err) => {\n            console.error(err);\n            res.sendStatus(500);\n        });\n\n    req.on('close', () => writeStream.destroy());\n});\n\napp.listen(3000);"
}
